package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class ScoutingCriterionService { private final ScoutingCriterionRepository criteria; public ScoutingCriterionService(ScoutingCriterionRepository criteria){this.criteria=criteria;} @Transactional public ScoutingCriterion createCriterion(ScoutingCriterion criterion){return criteria.save(criterion);} @Transactional public void setWeight(Long criterionId, Double weight){ScoutingCriterion c=criteria.findById(criterionId).orElseThrow(); c.setWeight(weight); criteria.save(c);} public List<ScoutingCriterion> listActiveCriteria(){return criteria.findByActiveTrue();} }
